const response = $context.getHttpResponse('existeAsesorResponse');
let payload = {};
try {
  payload = response.json();
} catch (e) {
  throw new Error('Respuesta inválida de botwa_existe_asesor');
}
let items = payload.data;
if (!Array.isArray(items)) {
  items = items ? [items] : [];
}
const existe = items.length > 0;
if (!existe) {
  $output.set('success', {
    existe: false,
    cliente: null,
    agencia: null,
    message: 'Cliente no encontrado en CRM'
  });
} else {
  const row = items[0] || {};
  $output.set('success', {
    existe: true,
    cliente: {
      id_usuario: String(row.id_usuario || ''),
      nombre_usuario: row.nombre_usuario || '',
      celular_usuario: row.celular_usuario || '',
      email_usuario: row.email_usuario || ''
    },
    agencia: {
      id_agencia: row.id_agencia != null ? String(row.id_agencia) : '',
      nombre_agencia: row.nombre_agencia || '',
      direccion_agencia: row.direccion_agencia || '',
      referencia_agencia: row.referencia_agencia || '',
      ubicacion_agencia: row.ubicacion_agencia || '',
      web_agencia: row.web_agencia || '',
      horario_agencia: row.horario_agencia || ''
    },
    message: 'Cliente encontrado en CRM'
  });
}

function readInput(name) {
  try { return String($input.get(name) ?? '').trim(); } catch (e) { return ''; }
}
const idMarca = readInput('id_marca');
let cedula = readInput('cedula').replace(/[^0-9]/g, '');
let celular = readInput('celular').replace(/[^0-9+]/g, '');
if (!idMarca || idMarca === '0') {
  throw new Error('id_marca es requerido');
}
if (!cedula) {
  throw new Error('cedula es requerida');
}
if (!celular) {
  throw new Error('celular es requerido');
}
// Si llega con +593..., deja dígitos; Baycentro acepta formato local o con prefijo.
celular = celular.replace(/^\+/, '');
$context.set('id_marca', idMarca);
$context.set('cedula', cedula);
$context.set('celular', celular);
